// 前端提取引用并发送到后端
function extractReferences(nodeId, content) {
  // 识别引用格式，如 [[nodeId]]、#tag 或 @person
  const references = content.match(/\[\[(.*?)\]\]|#(\w+)|@(\w+)/g) || [];

  if (references.length > 0) {
    fetch('/api/relations/references', {
      method: 'POST',
      body: JSON.stringify({
        source: nodeId,
        references: references.map(ref => ({
          type: ref.startsWith('[[') ? 'REFERENCES' : 
                ref.startsWith('#') ? 'TAGGED' : 'MENTIONS',
          target: ref.replace(/[\[\]#@]/g, '')
        }))
      })
    });
  }
}
