# 后端分析节点内容中的关键实体共现
def analyze_co_occurrence(node_id, text):
    # 提取关键实体（人名、地点、概念等）
    entities = extract_entities(text)

    # 查找数据库中包含相同实体的其他节点
    for entity in entities:
        similar_nodes = db.query(f"""
            MATCH (n:Node) 
            WHERE n.id <> '{node_id}' AND n.content CONTAINS '{entity}'
            RETURN n.id, count(*) as strength
        """)

        # 创建共现关系，强度基于共同实体数量
        for similar in similar_nodes:
            db.execute(f"""
                MATCH (a:Node {{id: '{node_id}'}}), (b:Node {{id: '{similar.id}'}})
                MERGE (a)-[r:CO_OCCURS]->(b)
                ON CREATE SET r.strength = {similar.strength}
                ON MATCH SET r.strength = {similar.strength}
            """)
