# 使用向量相似度发现相关节点
def create_semantic_relations(node_id, text):
    # 1. 计算文本的嵌入向量
    embedding = embed_text(text)

    # 2. 存入向量库
    vector_db.upsert(node_id, embedding, {"text": text[:100]})

    # 3. 查找相似节点
    similar_nodes = vector_db.query(
        embedding, 
        top_k=5,
        filter=f"id != '{node_id}'"
    )

    # 4. 创建语义关系
    for similar in similar_nodes:
        if similar.score > 0.75:  # 高相似度阈值
            db.execute(f"""
                MATCH (a:Node {{id: '{node_id}'}}), (b:Node {{id: '{similar.id}'}})
                MERGE (a)-[r:SEMANTICALLY_RELATED]->(b)
                SET r.score = {similar.score}
            """)
