# 分析节点内的会话时间戳，构建时序图
def extract_temporal_relations(node_id, content):
    # 从当前实现的_parseSessions()获取会话
    sessions = parse_sessions(content)
    if len(sessions) <= 1:
        return

    # 按时间排序
    sorted_sessions = sorted(sessions, key=lambda s: s['timestamp'])

    # 创建会话节点并连接时序关系
    previous_id = None
    for session in sorted_sessions:
        session_id = f"{node_id}_session_{session['timestamp']}"

        # 创建会话节点
        db.execute(f"""
            CREATE (s:Session {{
                id: '{session_id}',
                parent_node: '{node_id}',
                timestamp: '{session['timestamp']}',
                summary: '{session['text'][:100]}'
            }})
        """)

        # 连接到父节点
        db.execute(f"""
            MATCH (n:Node {{id: '{node_id}'}}), (s:Session {{id: '{session_id}'}})
            CREATE (n)-[:HAS_SESSION]->(s)
        """)

        # 创建会话间的时序关系
        if previous_id:
            db.execute(f"""
                MATCH (prev:Session {{id: '{previous_id}'}}),
                      (curr:Session {{id: '{session_id}'}})
                CREATE (prev)-[:FOLLOWED_BY]->(curr)
            """)

        previous_id = session_id
