// 在关系栏的fetchRelations方法中添加真实Neo4j后端调用
async function fetchRelations(nodeId) {
  if (!nodeId) return [];
  setStatus(`加载中...(${nodeId})`);
  try {
    const url = `/api/relations?nodeId=${encodeURIComponent(nodeId)}`;
    const resp = await fetch(url, { headers: { 'Accept': 'application/json' } });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);

    const data = await safeJSON(resp);
    // 结构化处理响应
    if (Array.isArray(data)) {
      // 原格式：[{id, type, source, target, direction, properties}]
      return data;
    } else if (data && Array.isArray(data.items)) {
      return data.items;
    } else if (data && Array.isArray(data.relationships)) {
      // 适配Neo4j返回的常见格式
      return data.relationships.map(rel => ({
        id: rel.id || `${rel.source}_${rel.type}_${rel.target}`,
        type: rel.type,
        source: rel.startNode || rel.source,
        target: rel.endNode || rel.target,
        direction: nodeId === (rel.startNode || rel.source) ? 'out' : 'in',
        properties: rel.properties || {}
      }));
    }

    // 非预期结构，回退
    throw new Error('unexpected payload');
  } catch(err) {
    console.warn('[relations] 使用 mock 数据:', err && err.message);
    // 同前保持mock数据
    return [
      { id: 'e1', type: 'KNOWS', source: nodeId, target: `${nodeId}-A`, direction: 'out', properties: { since: 2020 } },
      { id: 'e2', type: 'DEPENDS_ON', source: `${nodeId}-B`, target: nodeId, direction: 'in', properties: { weight: 0.7 } },
      { id: 'e3', type: 'RELATED', source: nodeId, target: `${nodeId}-C`, direction: 'out', properties: {} },
    ];
  }
}
