# FastAPI实现
from fastapi import FastAPI, HTTPException
from neo4j import GraphDatabase

app = FastAPI()
driver = GraphDatabase.driver("bolt://localhost:7687", auth=("neo4j", "password"))

# 获取节点关系API
@app.get("/api/relations")
async def get_relations(nodeId: str):
    with driver.session() as session:
        # 查询出边和入边
        result = session.run("""
            MATCH (node {id: $nodeId})
            OPTIONAL MATCH (node)-[out]->(target)
            OPTIONAL MATCH (source)-[in]->(node)
            RETURN 
                collect(distinct {
                    id: id(out),
                    type: type(out),
                    source: node.id,
                    target: target.id,
                    direction: 'out',
                    properties: properties(out)
                }) as outgoing,
                collect(distinct {
                    id: id(in),
                    type: type(in),
                    source: source.id,
                    target: node.id,
                    direction: 'in', 
                    properties: properties(in)
                }) as incoming
        """, nodeId=nodeId)

        data = result.single()
        if not data:
            return []

        # 合并出边和入边
        relationships = data["outgoing"] + data["incoming"]
        return relationships

# 创建关系API
@app.post("/api/relations")
async def create_relation(relation: dict):
    with driver.session() as session:
        # 检查节点是否存在
        source_exists = session.run(
            "MATCH (n {id: $id}) RETURN count(n) > 0 AS exists",
            id=relation["source"]
        ).single()["exists"]

        target_exists = session.run(
            "MATCH (n {id: $id}) RETURN count(n) > 0 AS exists", 
            id=relation["target"]
        ).single()["exists"]

        # 不存在则创建节点
        if not source_exists:
            session.run(
                "CREATE (n:Node {id: $id, title: $id})", 
                id=relation["source"]
            )

        if not target_exists:
            session.run(
                "CREATE (n:Node {id: $id, title: $id})", 
                id=relation["target"]
            )

        # 创建或更新关系
        result = session.run("""
            MATCH (source {id: $source}), (target {id: $target})
            MERGE (source)-[r:`$type`]->(target)
            SET r += $properties
            RETURN id(r) as id
        """, 
            source=relation["source"],
            target=relation["target"],
            type=relation["type"],
            properties=relation.get("properties", {})
        )

        return {"id": result.single()["id"]}
